import {BODIES,BY_ID,SIZES,placements,connections,isolated,reachable,footprint,boundaryWalls,portSegment,LANDING,ANNEX,levelsFor} from './architecture.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const colors={pass:'#3c8a60',view:'#d29b35',blocked:'#a67565'};
const line=(a,b,c='#647263',w=.12,dash='')=>`<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" stroke="${c}" stroke-width="${w}" ${dash?'stroke-dasharray="'+dash+'"':''}/>`;
export function floorSVG(sim,level,{phase=null,selected='R1'}={}){const planned=!!phase,state=phase??sim.phase,e=sim.experiment,p=planned?placements(state,e):sim.positions,links=planned?connections(state,e):sim.liveConnections,iso=isolated(state,e),y=levelsFor(e)[level];let s=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="-7.4 -2 63 29" role="img" aria-label="${level===1?'第三層':'第二層'} ${state} 可動廊下平面図"><defs><pattern id="well${level}" width="1" height="1" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><rect width="1" height="1" fill="#d4dacd"/><line x1="0" y1="0" x2="0" y2="1" stroke="#b9c3b0" stroke-width=".1"/></pattern><pattern id="isolate${level}" width="1" height="1" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><line x1="0" y1="0" x2="0" y2="1" stroke="#a97545" stroke-width=".15"/></pattern></defs><rect x="0" y="0" width="49.2" height="24.4" fill="url(#well${level})" stroke="#a8b79d" stroke-width=".13"/><rect x="-6.4" y="0" width="4" height="4" fill="#a8bba0" stroke="#6e8865" stroke-width=".12"/><text x="-4.4" y="2.5" text-anchor="middle" font-size="1" fill="#45613c">EV</text><rect x="-2.4" y="0" width="2" height="4" fill="#b9c7ad"/>`;
 if(level===0){const c=links.find(c=>c.b==='ANNEX'),status=c?.status??'blocked';s+=`<rect x="${ANNEX.x}" y="0" width="4" height="4" fill="#b7c4a8" stroke="#7a8e70" stroke-width=".12"/><text x="51.6" y="1.7" text-anchor="middle" font-size=".65" fill="#4b6443">固定</text><text x="51.6" y="2.7" text-anchor="middle" font-size=".65" fill="#4b6443">観察室</text>${line([ANNEX.x,1],[ANNEX.x,3],colors[status],.28)}`;if(!reachable(state,e).has('ANNEX'))s+=`<rect x="${ANNEX.x}" y="0" width="4" height="4" fill="url(#isolate${level})"/>`;}
 for(const c of links)if(c.level===level&&c.status==='pass'){const b=c.bridge;s+=`<rect x="${b.x}" y="${b.z}" width="${b.w}" height="${b.d}" fill="#a7b58a"/>`;}
 for(const b of BODIES){const q=p[b.id];if(Math.abs(q.y-y)>.1)continue;s+=`<g data-id="${b.id}" transform="translate(${q.x} ${q.z})">`;for(const [i,[cx,cz]]of b.cells.entries())s+=`<rect x="${cx*8}" y="${cz*8}" width="8" height="8" fill="${b.color}" stroke="${selected===b.id?'#354f43':'#dce3d3'}" stroke-width="${selected===b.id?.23:.12}"/><text x="${cx*8+.4}" y="${cz*8+7.5}" font-size=".65" fill="#385046">${b.id}.${i+1}</text>`;for(const o of b.solids)s+=`<rect x="${o.x}" y="${o.z}" width="${o.w}" height="${o.d}" fill="#667768" opacity=".72"/>`;for(const o of b.furniture)s+=`<rect x="${o.x}" y="${o.z}" width="${o.w}" height="${o.d}" fill="#666e55" opacity=".35"/>`;for(const l of[...boundaryWalls(b),...b.walls])s+=line(l.a,l.b,'#4f6558',.13);for(const d of b.doors)s+=line(d.a,d.b,d.locked?'#a76d56':'#e8ead9',.23,d.glass?'.2 .15':'');for(const port of b.ports){const l=portSegment(b,port),c=links.find(c=>c.ports[b.id]===port.face);s+=line(l.a,l.b,colors[c?.status??'blocked'],.32);}if(iso.includes(b.id))for(const[cx,cz]of b.cells)s+=`<rect x="${cx*8}" y="${cz*8}" width="8" height="8" fill="url(#isolate${level})"/>`;for(const l of b.labels)s+=`<text x="${l.x}" y="${l.z}" text-anchor="middle" font-size="${l.name.length>8?.6:.72}" fill="#344e43">${esc(l.name)}</text>`;s+='</g>';}
 if(!planned&&Math.abs(sim.player.y-y)<.1){const q=sim.player;s+=`<circle cx="${q.x}" cy="${q.z}" r=".45" fill="#cd6045" stroke="#f7f7e9" stroke-width=".15"/>${line([q.x,q.z],[q.x+Math.sin(q.yaw)*1.5,q.z+Math.cos(q.yaw)*1.5],'#cd6045',.16)}`;}
 s+=`<text x="15" y="20" text-anchor="middle" font-size=".9" fill="#7b8b70">斜線域：搬送井・床なし</text><text x="48" y="26" text-anchor="end" font-size=".8" fill="#849278">N ↑　8m ━</text></svg>`;return s;
}
export function deckSVG(sim){const e=sim.experiment,bound=SIZES[e.size],d=bound.d;let s=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="-7 -4 ${bound.w+14} ${d+11}" role="img" aria-label="搬送範囲・途中の掃引領域・高さ別占有"><rect x="0" y="0" width="${bound.w}" height="${d}" fill="#d8e1cf" stroke="#8ea683" stroke-width=".2"/><rect x="0" y="0" width="49.2" height="24.4" fill="none" stroke="#637f5a" stroke-width=".2" stroke-dasharray=".6 .4"/>`;
 for(let z=0;z<d;z+=8.4)s+=line([0,z],[bound.w,z],'#b8c7ad',.09);for(let x=0;x<bound.w;x+=8.4)s+=line([x,0],[x,d],'#b8c7ad',.09);
 if(sim.plan)for(const st of sim.plan.stages)for(const m of st.motions){const f=footprint(BY_ID[m.id]);s+=line([m.from.x+f.w/2,m.from.z+f.d/2],[m.to.x+f.w/2,m.to.z+f.d/2],BY_ID[m.id].color,.16,'.6 .4');}
 const stage=sim.mode==='moving'?sim.plan?.stages[sim.stageIndex]:null;if(stage)for(const m of stage.motions)for(const[cx,cz]of BY_ID[m.id].cells){const x=Math.min(m.from.x,m.to.x)+cx*8,z=Math.min(m.from.z,m.to.z)+cz*8,w=8+Math.abs(m.to.x-m.from.x),dd=8+Math.abs(m.to.z-m.from.z);s+=`<rect x="${x}" y="${z}" width="${w}" height="${dd}" fill="#d5ae4c" fill-opacity=".18" stroke="#b99137" stroke-width=".15"/>`;}
 for(const b of BODIES){const p=sim.positions[b.id],f=footprint(b);s+=`<g data-id="${b.id}" transform="translate(${p.x} ${p.z})" opacity="${p.y>0&&p.y<sim.levels[1]?1:.5}">`;for(const[cx,cz]of b.cells)s+=`<rect x="${cx*8+.1}" y="${cz*8+.1}" width="7.8" height="7.8" fill="${b.color}" stroke="#506c55" stroke-width=".13"/>`;s+=`<text x="${f.w/2}" y="${f.d/2}" text-anchor="middle" font-size="1.2" fill="#334e41">${b.id}</text><text x="${f.w/2}" y="${f.d/2+1.5}" text-anchor="middle" font-size=".95" fill="#425d49">y ${p.y.toFixed(1)}m</text></g>`;}
 s+=`<circle cx="${sim.player.x}" cy="${sim.player.z}" r=".45" fill="#cd6045" stroke="#fff" stroke-width=".15"/><text x="${bound.w/2}" y="${d+3}" text-anchor="middle" font-size="1.05" fill="#5e7655">${bound.w} × ${bound.d}m ／ 高さ別の平面投影</text><text x="${bound.w/2}" y="${d+5}" text-anchor="middle" font-size=".85" fill="#738668">黄：現在区間の掃引 ／ 衝突は3D連続検査</text></svg>`;return s;}
